-- Full Spectrum grants: batch 9 (pasted research notes 2026-11-01, third round; funder details from the notes, official pages not re-opened by us).
-- 10 new opportunities plus 3 rejected leads kept as not_eligible so they are not researched again. Idempotent; safe to re-run.
-- Apply: supabase db query --linked -f supabase/fs-grants-batch9.sql
begin;
select count(*) as before_total from fs_grant_deadlines;
insert into fs_grant_deadlines (funder, program, kind, deadline_date, opens_date, amount, verified, url, notes, verified_on, level, project, priority, eligibility, match_required, status, gates, next_step, next_step_due)
select * from (values
('SBB Research Group Foundation','Monthly grants','rolling',null::date,null::date,'$5,000 winner; $1,000 other finalists',false,'https://www.sbbrg.org/apply-for-grant','Any 501(c)(3) may apply; PREFERENCE for organizations with 5-49 full-time employees (not stated as an exclusion). Short online application, then interview or presentation if selected. Monthly selections; one application per calendar year. Funded a similar Chicago youth arts and technology group (The Brown House Experience, $5,000). Request: $5,000 for a defined DJ Lab teaching block (instructor hours at $250 a session, guest DJ fees, a quoted equipment gap).','2026-11-01'::date,'foundation','djclass',1,'Any 501(c)(3); prefers 5-49 employees',null,'to_research','{g0}'::text[],'Write a clear $5,000 request and submit the short application at sbbrg.org/grant-application',null::date),
('Digitunity','Technology donation matching (laptops)','rolling',null,null,'donated computers; no fixed quantity',false,'https://digitunity.org/get-involved/receive-equipment/','Apply as an organization. IRS documentation required; equipment must benefit participants. Matching is not guaranteed; review about a month. Ask for 12 Windows laptops for the 12 stations (state software needs, ports, chargers, condition) and accept partial fulfillment. Confirm classroom use, delivery costs and minimum specs.','2026-11-01'::date,'foundation','djclass',1,'US nonprofit serving people facing technology-access barriers',null,'to_research','{g0}'::text[],'Apply as an organization with the laptop specification sheet',null),
('4imprint','one by one (promotional products)','rolling',null,null,'$500 toward promotional products',false,'https://onebyone.4imprint.com/application','An employee or board member age 18+ must apply. One award per 12 months. Apply at least TWO MONTHS before items are needed; winners must order within 30 days; orders over $500 cost the difference. A music-program recipient used it for tags on donated instruments. Idea: student equipment-bag tags and reusable outreach materials.','2026-11-01'::date,'corporate','djclass',2,'Nonprofit employee or board member 18+',null,'to_research','{g0}'::text[],'Get a quote under $500 including shipping and setup, then apply 2+ months before the need',null),
('Patrick & Anna M. Cudahy Fund','Program or general operating (LOI)','rolling',null,null,'range not published',false,'https://www.cudahyfund.org/guidelines','Metropolitan Chicago eligible; education includes after-school programs. EVENT SPONSORSHIPS EXCLUDED: propose the DJ Lab, not a party. Online introductory LOI year-round; full proposal by invitation; board usually meets spring and fall. Questions: laurenkrieg@cudahyfund.org. The published proposal date had no year: do not treat it as a deadline.','2026-11-01'::date,'foundation','djclass',2,'Metro Chicago; no event sponsorships',null,'to_research','{g0,g4}'::text[],'Submit a concise DJ Lab introduction through the online LOI',null),
('Computers with Causes','Computer donations','rolling',null,null,'donated computers; inventory dependent',false,'https://www.computerswithcauses.org/application/','Download the schools/organizations PDF, sign it and MAIL it (no email or online submission). Valid 30 days from postmark, then reapply. Assessed on needs, references and inventory; a full matching set is not guaranteed. Specify software-compatible Windows laptops.','2026-11-01'::date,'foundation','djclass',2,'Nonprofits and community programs',null,'to_research','{g0}'::text[],'Complete, sign and mail the organization application',null),
('Oriental Trading','Corporate giving donation request','rolling',null,null,'package not published',false,'https://orientaltrading.requestitem.com/','Current 501(c)(3) required; attach the determination letter. Priorities include education and youth. The form is event oriented and asks about fundraising: state accurately that family participation is free. Submit at least FOUR WEEKS before the event. Ask for craft materials for youth-designed decorations and color-themed art sessions.','2026-11-01'::date,'corporate','wednesdays',3,'501(c)(3); event 4+ weeks out',null,'to_research','{g0}'::text[],'Build an itemized materials request tied to a named Rainbow Wednesday',null),
('Taproot Foundation','Taproot Plus (free professional volunteers)','rolling',null,null,'free pro bono services',false,'https://taprootfoundation.org/nonprofits','Skilled volunteers for a well-scoped project: financial model, sponsorship presentation, fundraising strategy or communications plan. Open to nonprofits of any size. Needs staff time and a concrete deliverable.','2026-11-01'::date,'foundation','org',2,'Any US nonprofit',null,'to_research','{}'::text[],'Sign up and request a focused budget-and-sponsorship review',null),
('The Make Sense Foundation','Grants (women and children in need)','rolling',null,null,'monetary and in-kind; range not published',false,'https://makesensefoundation.org/apply-for-a-grant/','Supports 501(c)(3)s serving women and children in need. Requests backed by SeneGence distributors get priority; nothing says you must become one. Initial review 5-10 business days; board votes quarterly. CONFIRM Chicago coverage and newer-organization eligibility first: info@makesensefoundation.org. Possible fit: free music education and the girls mentorship component.','2026-11-01'::date,'foundation','djclass',3,'501(c)(3) serving women and children in need',null,'to_research','{g0}'::text[],'Email info@makesensefoundation.org to confirm Chicago and new-organization eligibility',null),
('Listen Technologies','Product donations (assistive listening)','rolling',null,null,'assistive-listening products',false,'https://www.listentech.com/request-a-donation/','Assistive-listening equipment only: NOT controllers, PA speakers or general headphones. Needs a real accessibility need (participants or audience). Geography, organization-age rules and installation costs not published. Allocated annually.','2026-11-01'::date,'corporate','wednesdays',4,'Documented assistive-listening need',null,'to_research','{}'::text[],'Decide whether a real accessibility need exists before applying',null),
('COUNTRY Financial','Local community contributions','relationship',null,null,'not published',false,'https://www.countryfinancial.com/en/about-us/in-your-community.html','Requests outside Bloomington-Normal go through local representatives. An access route, not a confirmed arts fit. Use Find a local rep, identify one serving South Shore, ask about community contributions for a defined youth instruction or guest-mentor expense.','2026-11-01'::date,'corporate','djclass',4,'Locally determined',null,'to_research','{g4}'::text[],'Find the South Shore representative and ask for a community-contribution conversation',null),
('William G. McGowan Charitable Fund','Chicago grants','paused',null,null,'not published',true,'https://williamgmcgowanfund.org/how-to-apply/','Chicago eligibility limited to Austin and North Lawndale; no new applicants for 2026. Not a fit.','2026-11-01'::date,'foundation','org',5,'Austin and North Lawndale only',null,'not_eligible','{}'::text[],'None',null),
('BNSF Railway Foundation','Grants','paused',null,null,'not published',true,'https://www.bnsffoundation.org/policies/','Excludes startup or seed funding and requires meaningful BNSF connections. Not a fit now.','2026-11-01'::date,'corporate','org',5,'No startup funding; BNSF connection',null,'not_eligible','{}'::text[],'None',null),
('Electronic Reusing Association','Computer donation requests','paused',null,null,'donated computers',true,'https://www.electronicreusingassociation.us/prime/get-involved/','Current request page is limited to Florida. Not a fit.','2026-11-01'::date,'foundation','org',5,'Florida only',null,'not_eligible','{}'::text[],'None',null)
) as v(funder,program,kind,deadline_date,opens_date,amount,verified,url,notes,verified_on,level,project,priority,eligibility,match_required,status,gates,next_step,next_step_due)
where not exists (select 1 from fs_grant_deadlines g where g.funder = v.funder and g.program = v.program);
select count(*) as after_total from fs_grant_deadlines;
commit;
